def inside(pt, poly):
    x, y = pt
    c = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if x < xi:
                c = not c
    return c


def is_land(lon, lat):
    if any(inside((lon, lat), p) for p in HOLES.values()):
        return False
    return any(inside((lon, lat), p) for p in LAND.values())


def fmt(v):
    s = ("%.2f" % v).rstrip("0").rstrip(".")
    return s


runs = []
count = 0
lat = TOP - STEP / 2
while lat > BOTTOM:
    lon = -180 + STEP / 2
    start = None
    prev = None
    while lon < 180:
        land = is_land(lon, lat)
        if land:
            count += 1
            if start is None:
                start = lon
            prev = lon
        elif start is not None:
            runs.append((start, prev, lat))
            start = None
        lon += STEP
    if start is not None:
        runs.append((start, prev, lat))
    lat -= STEP

parts = []
for a, b, la in runs:
    x = a + 180
    y = TOP - la
    length = b - a
    parts.append("M%s %sh%s" % (fmt(x), fmt(y), fmt(length + 0.01)))
d = "".join(parts)
print(json.dumps({"dots": count, "runs": len(runs), "chars": len(d), "height": TOP - BOTTOM}), file=sys.stderr)
print(d)
